solution:
function RobLine(nums: int[], lo: int, hi: int) -> int {
  let prev = 0;
  let cur = 0;
  let i = lo;
  while (i <= hi) {
    let take = prev + nums[i];
    let next = take;
    if (cur > take) {
      next = cur;
    }
    prev = cur;
    cur = next;
    i += 1;
  }
  return cur;
}

function Rob2(nums: int[]) -> int {
  let n = nums.length();
  if (n == 1) {
    return nums[0];
  }
  let a = RobLine(nums, 0, n - 2);
  let b = RobLine(nums, 1, n - 1);
  if (a > b) {
    return a;
  }
  return b;
}
